/*
GPT-2 Transformer Neural Net training loop. SYCL 2020 port of train_gpt2.cu
for Intel oneAPI DPC++ (icpx -fsycl). Single device, bf16 mixed precision
(ENABLE_BF16 default), oneMath BLAS column_major bf16->fp32 gemms, SYCL group
algorithms for reductions. Keeps llm.c's command line, printout and file formats.
*/
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string>
#include <string_view>
#include <sys/stat.h>
#include <sys/types.h>
#include <chrono>
// ----------- CPU utilities -----------
#include "llmc/utils.h"
#include "llmc/tokenizer.h"
#include "llmc/dataloader.h"
#include "llmc/rand.h"
#include "llmc/schedulers.h"
#include "llmc/sampler.h"
#include "llmc/logger.h"
#include "llmc/mfu.h"
#include "llmc/outlier_detector.h"
// ----------- SYCL utilities -----------
#include "llmc/sycl_common.h"
#include "llmc/sycl_utils.hpp"
// ----------- Layer implementations in SYCL -----------
#include "llmc/encoder.hpp"
#include "llmc/layernorm.hpp"
#include "llmc/matmul.hpp"
#include "llmc/attention.hpp"
#include "llmc/fused_classifier.hpp"
#include "llmc/adamw.hpp"
#include "llmc/global_norm.hpp"
// ----------- Single-device support -----------
#include "llmc/zero.hpp"

// ----------------------------------------------------------------------------
// global vars for I/O
char filename_buffer[512];

// ----------------------------------------------------------------------------
// global vars containing information about the SYCL device this process is running on
sycl::queue sycl_queue;
std::string sycl_device_name = "SYCL device";
// buffer size to use for device <-> disk io (kept for API compat; USM is host-visible)
constexpr const size_t IO_BUF_SIZE = 32 * 1024 * 1024;

// USM allocation helpers (shared memory: accessible on host and device)
inline void* sycl_malloc_shared(size_t bytes) {
    if (bytes == 0) { return nullptr; }
    void* p = sycl::malloc_shared(bytes, sycl_queue);
    if (!p) { printf("[SYCL ERROR] malloc_shared failed for %zu bytes\n", bytes); exit(EXIT_FAILURE); }
    return p;
}

// ----------------------------------------------------------------------------
// GPT-2 model definition

typedef struct {
    int max_seq_len; // max sequence length, e.g. 1024
    int vocab_size; // vocab size, e.g. 50257
    int padded_vocab_size; // padded to e.g. %128==0, 50304
    int num_layers; // number of layers, e.g. 12
    int num_heads; // number of heads in attention, e.g. 12
    int channels; // number of channels, e.g. 768
} GPT2Config;

// the parameters of the model
constexpr const int NUM_PARAMETER_TENSORS = 16;
typedef struct {
    floatX* wte; // (V, C)
    floatX* wpe; // (maxT, C)
    floatX* ln1w; // (L, C)
    floatX* ln1b; // (L, C)
    floatX* qkvw; // (L, 3*C, C)
    floatX* qkvb; // (L, 3*C)
    floatX* attprojw; // (L, C, C)
    floatX* attprojb; // (L, C)
    floatX* ln2w; // (L, C)
    floatX* ln2b; // (L, C)
    floatX* fcw; // (L, 4*C, C)
    floatX* fcb; // (L, 4*C)
    floatX* fcprojw; // (L, C, 4*C)
    floatX* fcprojb; // (L, C)
    floatX* lnfw; // (C)
    floatX* lnfb; // (C)
} ParameterTensors;
static_assert(sizeof(ParameterTensors) == NUM_PARAMETER_TENSORS * sizeof(void*), "Inconsistent sizes!");

void fill_in_parameter_sizes(size_t* param_sizes, size_t* param_sizeof, GPT2Config config) {
    size_t Vp = config.padded_vocab_size;
    size_t C = config.channels;
    size_t maxT = config.max_seq_len;
    size_t L = config.num_layers;
    param_sizes[0] = Vp * C; // wte
    param_sizes[1] = maxT * C; // wpe
    param_sizes[2] = L * C; // ln1w

#define TESTING
#include "train_gpt2.cpp"

// poor man's tensor checker
int check_tensor(float *a, float *b, int n, const char* label, float threshold=1e-0) {
    // a is the calculated tensor, b is the reference tensor
    int print_upto = 10;
    int ok = 1;
    float max_diff = 0.0f;
    float max_rel_error = 0.0f;
    float max_to_threshold = 0.f;
    float max_a = 0.0f;
    float max_b = 0.0f;
    float epsilon = 0.079;      // BF16 epsilon value
    printf("---\n");
    printf("checking tensor: %s\n", label);
    for (int i = 0; i < n; i++) {
        float t_eff = threshold + fabs(b[i]) * epsilon;
        float diff = fabsf(a[i] - b[i]);
        max_to_threshold = std::max(max_to_threshold, diff / t_eff);
        if (diff > max_diff) {
            max_diff = diff;
            float denom = fabsf(b[i]);
            max_rel_error = (denom == 0.0f) ? 0.0f : diff / denom;
            max_a = a[i];
            max_b = b[i];
        }
        if (diff > t_eff) {
            ok = 0;
        }
        // print the first few elements so we can visually assess the "proof" of the comparison
        if (i < print_upto) {
            printf(diff <= t_eff ? "OK " :  "NOT OK ");
            printf("%f %f\n", a[i], b[i]);
        }
    }
    // print the final result
    if (ok) {
        printf("TENSOR OK, max diff: %.3e, with rel error: %.3e (calculated=%10f, ref=%10f), %.2f%% of maximum error\n",
                max_diff, max_rel_error, max_a, max_b, max_to_threshold*100);
    } else {
        printf("TENSOR NOT OK, max diff: %.3e, with rel error: %.3e (calculated=%10f, ref=%10f), %.2f%% of maximum error\n",
                max_diff, max_rel_error, max_a, max_b, max_to_threshold*100);
    }
    return ok;
}

// the same tensors as in the train file, but in float, which are used as reference
typedef struct {
    float*  wte; // (Vp, C)
    float*  wpe; // (maxT, C)
    float*  ln1w; // (L, C)
    float*  ln1b; // (L, C)
    float*  qkvw; // (L, 3*C, C)
    float*  qkvb; // (L, 3*C)
    float*  attprojw; // (L, C, C)
    float*  attprojb; // (L, C)
    float*  ln2w; // (L, C)
    float*  ln2b; // (L, C)
    float*  fcw; // (L, 4*C, C)
    float*  fcb; // (L, 4*C)
    float*  fcprojw; // (L, C, 4*C)
    float*  fcprojb; // (L, C)
    float*  lnfw; // (C)
    float*  lnfb; // (C)
} FloatParameterTensors;
static_assert(sizeof(FloatParameterTensors) == NUM_PARAMETER_TENSORS * sizeof(void*), "Inconsistent sizes!");

// malloc_and_point, but in float and on CPU, because we use this data to check correctness on CPU
float* float_cpu_malloc_and_point_parameters(FloatParameterTensors* params, size_t* param_sizes) {
    // calculate the total number of parameters
    size_t num_parameters = 0;
    for (int i = 0; i < NUM_PARAMETER_TENSORS; i++) {
        num_parameters += param_sizes[i];
    }
    // everything is float so number of bytes to allocate is a simple multiplication
    float* params_memory = (float*)mallocCheck(num_parameters * sizeof(float));
    float** ptrs[] = {
        &params->wte, &params->wpe, &params->ln1w, &params->ln1b, &params->qkvw, &params->qkvb,
        &params->attprojw, &params->attprojb, &params->ln2w, &params->ln2b, &params->fcw, &params->fcb,
        &params->fcprojw, &params->fcprojb, &params->lnfw, &params->lnfb
    };
    float* params_memory_iterator = params_memory;
    for (int i = 0; i < NUM_PARAMETER_TENSORS; i++) {
        *(ptrs[i]) = params_memory_iterator;
        params_memory_iterator += param_sizes[i];
    }
    return params_memory;
}

int main(int argc, char *argv[]) {
    char nccl_init_method[256] = "mpi";  // "tcp" or "fs" or "mpi"
    int num_processes = -1;  // doesn't matter when using MPI
    int process_rank = -1;  // doesn't matter when using MPI
    int gpus_per_node = -1;  // doesn't matter when using MPI
    char server_ip[256] = "";  // doesn't matter when using MPI
    char fs_path[256] = "";  // doesn't matter when using MPI
    multi_gpu_config = multi_gpu_config_init(num_processes, process_rank, gpus_per_node, server_ip, fs_path, nccl_init_method);
    common_start(false, true);

/*
Common utilities for SYCL code (port of cuda_common.h).
Single SYCL device, USM shared allocations, in-order queue.
*/
#ifndef SYCL_COMMON_H
#define SYCL_COMMON_H

#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <string>
#include <type_traits>      // std::bool_constant
#include <cstdint>
#include <sycl/sycl.hpp>
#include <sycl/ext/oneapi/bfloat16.hpp>

#include "utils.h"

// ----------------------------------------------------------------------------
// Global defines and settings

// Single SYCL device queue used by the whole program (created in train file).
extern sycl::queue sycl_queue;

// Block size used for 1-D kernels (tunable, no CUDA meaning)
#define SYCL_BLOCK_SIZE 256u

// convenience macro for calculating grid dimensions for kernels
#define CEIL_DIV(M, N) (((M) + (N)-1) / (N))

// short-cuts for compile-time boolean values that can be used as function arguments
constexpr std::bool_constant<true> True;
constexpr std::bool_constant<true> False;

// ----------------------------------------------------------------------------
// Error checking helpers for SYCL allocations

template<class T>
inline void syclFreeCheck(T* &ptr) {
    if (ptr) { sycl::free(ptr, sycl_queue); ptr = nullptr; }
}

// ----------------------------------------------------------------------------
// SYCL Precision settings and defines

enum PrecisionMode {
    PRECISION_FP32,
    PRECISION_FP16,
    PRECISION_BF16
};

// Specific configurations based on the enabled precision
#if defined(ENABLE_FP32)
typedef float floatX;
#define PRECISION_MODE PRECISION_FP32
#elif defined(ENABLE_FP16)
typedef sycl::half floatX;
#define PRECISION_MODE PRECISION_FP16
#else // Default to bfloat16
typedef sycl::ext::oneapi::bfloat16 floatX;
#define PRECISION_MODE PRECISION_BF16
#endif

// ----------------------------------------------------------------------------
// Profiler utils (no-op in SYCL port)

class NvtxRange {
 public:
    NvtxRange(const char* s) { (void)s; }
    NvtxRange(const std::string& base_str, int number) { (void)base_str; (void)number; }
    ~NvtxRange() { }
};
#define NVTX_RANGE_FN() NvtxRange nvtx_range(__FUNCTION__)

// ----------------------------------------------------------------------------
// Utilities to Read & Write between SYCL (USM-shared) memory <-> files
// USM shared pointers are directly accessible from the host, so plain fread/fwrite
// of the memory contents preserves llm.c's file formats bit-for-bit.

inline void device_to_file(FILE* dest, void* src, size_t num_bytes, size_t buffer_size, sycl::queue& q) {
    (void)buffer_size;
    q.wait();
    fwriteCheck(src, 1, num_bytes, dest);
}

inline void file_to_device(void* dest, FILE* src, size_t num_bytes, size_t buffer_size, sycl::queue& q) {
    (void)buffer_size;
    freadCheck(dest, 1, num_bytes, src);
    q.wait();
}

#endif // SYCL_COMMON_H

    param_sizes[2] = L * C; // ln1w
    param_sizes[3] = L * C; // ln1b
    param_sizes[4] = L * (3 * C) * C; // qkvw
    param_sizes[5] = L * (3 * C); // qkvb
    param_sizes[6] = L * C * C; // attprojw
    param_sizes[7] = L * C; // attprojb
    param_sizes[8] = L * C; // ln2w
    param_sizes[9] = L * C; // ln2b
    param_sizes[10] = L * (4 * C) * C; // fcw
    param_sizes[11] = L * (4 * C); // fcb
    param_sizes[12] = L * C * (4 * C); // fcprojw
    param_sizes[13] = L * C; // fcprojb
    param_sizes[14] = C; // lnfw
    param_sizes[15] = C; // lnfb

    // populate the parameter sizes in bytes (all the same for now, keeping for future use)
    for (int i = 0; i < NUM_PARAMETER_TENSORS; i++) {
        param_sizeof[i] = sizeof(floatX);
    }
}

// allocate memory for the parameters and point the individual tensors to the right places
void* malloc_and_point_parameters(ParameterTensors* params, size_t* param_elements, size_t *param_sizeof) {
    // calculate the total number of parameters and bytes across all tensors
    size_t num_parameters_bytes = 0;
    for (int i = 0; i < NUM_PARAMETER_TENSORS; i++) {
        num_parameters_bytes += param_elements[i] * param_sizeof[i];
    }
    // malloc all parameters all at once (USM shared)
    void* params_memory = sycl_malloc_shared(num_parameters_bytes);
    // assign all the tensors their place in the array
    floatX** ptrs[] = {
        &params->wte, &params->wpe, &params->ln1w, &params->ln1b, &params->qkvw, &params->qkvb,
        &params->attprojw, &params->attprojb, &params->ln2w, &params->ln2b, &params->fcw, &params->fcb,
        &params->fcprojw, &params->fcprojb, &params->lnfw, &params->lnfb
    };
    char* params_memory_iterator = (char*)params_memory;
    for (int i = 0; i < NUM_PARAMETER_TENSORS; i++) {
        *(ptrs[i]) = (floatX*)params_memory_iterator;
        params_memory_iterator += param_elements[i] * param_sizeof[i];
    }
    return params_memory;
}

constexpr int NUM_ACTIVATION_TENSORS = 21;
typedef struct {
    floatX* encoded; // (B, T, C)
    floatX* ln1; // (L, B, T, C)
    float* ln1_mean; // (L, B, T)
    float* ln1_rstd; // (L, B, T)
    floatX* atty; // (L, B, T, C)
    floatX* att; // (L, B, NH, T, T)
    floatX* residual2; // (L, B, T, C)
    floatX* ln2; // (L, B, T, C)
    float* ln2_mean; // (L, B, T)
    float* ln2_rstd; // (L, B, T)
    floatX* fch; // (L, B, T, 4*C)
    floatX* fch_gelu; // (L, B, T, 4*C)
    floatX* residual3; // (L, B, T, C)
    floatX* lnf; // (B, T, C);   if LN recomputation is enabled (-r 2 and above), will be used for _all_ layernorms
    float* lnf_mean; // (B, T)
    float* lnf_rstd; // (B, T)
    float* losses; // (B, T), will be accumulated in micro-steps
    // adding these two compared to the CPU .c code, needed for attention kernel as buffers
    floatX* qkvr; // (L, B, T, 3*C)
    // in inference mode, this buffer will store the logits
    // in training mode, this buffer will contain the *gradients* of the logits.
    // during the processing of transformer blocks, we will also use this as a
    // general scratchpad buffer. Allocation is made large enough to hold (B, T, 3C),
    // (B, NH, T, T), and (B, T, V) shaped tensors.
    floatX* output;

    // some additional scratch buffers
    floatX* scratch_bt4c;   // (B, T, 4*C)
    floatX* scratch_btc;    // (B, T, C)
    // fp32 scratch for oneMath gemm outputs (max over all matmuls) + batched attention tmp
    float* gemm_scratch;    // (max(OC*BT)) fp32
} ActivationTensors;


struct TensorSpec {
    void** ptr;
    size_t size;
    DType type;
};


#define TENSOR_SPEC(pointer, size) TensorSpec{(void**)(&pointer), (size), dtype_of(pointer)};

void fill_in_activation_sizes(const ActivationTensors* data, TensorSpec (&tensors)[NUM_ACTIVATION_TENSORS], size_t B, size_t T, GPT2Config config, int recompute) {
    size_t Vp = config.padded_vocab_size;
    size_t L = config.num_layers;
    size_t NH = config.num_heads;
    size_t C = config.channels;
    tensors[0] = TENSOR_SPEC(data->encoded, B * T * C);
    // if recompute >= 1 then we will recompute the layernorm forward activation during backward pass
    tensors[1] = TENSOR_SPEC(data->ln1,  (recompute < 2) ? L * B * T * C : 0);
    tensors[2] = TENSOR_SPEC(data->ln1_mean, L * B * T);
    tensors[3] = TENSOR_SPEC(data->ln1_rstd, L * B * T);
    tensors[4] = TENSOR_SPEC(data->atty, L * B * T * C);
    tensors[5] = TENSOR_SPEC(data->att, L * B * NH * T * T);
    tensors[6] = TENSOR_SPEC(data->residual2, L * B * T * C);
    // if recompute >= 1 then we will recompute the layernorm forward activation during backward pass
    tensors[7] = TENSOR_SPEC(data->ln2, (recompute < 2) ? L * B * T * C : 0);
    tensors[8] = TENSOR_SPEC(data->ln2_mean, L * B * T);
    tensors[9] = TENSOR_SPEC(data->ln2_rstd, L * B * T);
    tensors[10] = TENSOR_SPEC(data->fch, L * B * T * 4*C);
    // if recompute >= 1 then we will recompute gelu_forward during backward and use this as scratch buffer
    tensors[11] = TENSOR_SPEC(data->fch_gelu, (recompute < 1) ? L * B * T * 4*C : B * T * 4*C);
    tensors[12] = TENSOR_SPEC(data->residual3, L * B * T * C);
    tensors[13] = TENSOR_SPEC(data->lnf, B * T * C);
    tensors[14] = TENSOR_SPEC(data->lnf_mean, B * T);
    tensors[15] = TENSOR_SPEC(data->lnf_rstd, B * T);
    tensors[16] = TENSOR_SPEC(data->losses, B * T);
    tensors[17] = TENSOR_SPEC(data->qkvr, L * B * T * 3*C);
    tensors[18] = TENSOR_SPEC(data->output, B * T * std::max((size_t)(3*C), std::max((size_t)(NH*T), (size_t)Vp)));

    tensors[19] = TENSOR_SPEC(data->scratch_bt4c, B * T * 4 * C);
    tensors[20] = TENSOR_SPEC(data->scratch_btc, B * T * C);
}

// set the right paths
#if defined(ENABLE_BF16)
const char* load_filename = "gpt2_124M_bf16.bin";
#else
const char* load_filename = "gpt2_124M.bin";
#endif

// build the GPT-2 model from a checkpoint
GPT2 model;
gpt2_init_common(&model);

gpt2_build_from_checkpoint(&model, load_filename);
size_t V = model.config.vocab_size;
size_t Vp = model.config.padded_vocab_size;
size_t maxT = model.config.max_seq_len;

for (int i = 1; i < argc; i+=2) {
    if (i + 1 >= argc) { exit(EXIT_FAILURE);  } // must have arg after flag
    if (!(strlen(argv[i]) == 2 || strlen(argv[i]) == 3)) { exit(EXIT_FAILURE); } // must be -x[y] (one dash, one or two letters)
    if (argv[i][0] != '-') { exit(EXIT_FAILURE); } // must start with dash
    if (argv[i][1] == 'w') { model.use_master_weights = atoi(argv[i+1]); }
    else if (argv[i][1] == 'r') { model.recompute = atoi(argv[i+1]); }
    else if (argv[i][1] == 'g' && argv[i][2] == 'e') { model.gelu_fusion = atoi(argv[i+1]); }
}

// load additional information that we will use for debugging and error checking
FILE *state_file = fopenCheck("gpt2_124M_debug_state.bin", "rb");
int state_header[256];
freadCheck(state_header, sizeof(int), 256, state_file);
if (state_header[0] != 20240327) { fprintf(stderr, "Bad magic state file\n"); exit(EXIT_FAILURE); }
if (state_header[1] != 2) {
    fprintf(stderr, "Bad version in state file\n");
    fprintf(stderr, "---> HINT: try to re-run `python train_gpt2.py`\n");
    exit(EXIT_FAILURE);
}
int B = state_header[2]; // batch size, e.g. 4
int T = state_header[3]; // time / sequence length (e.g. 64, up to maxT)
assert(0 <= T && T <= (int)maxT);
printf("[State]\n");
printf("batch_size: %d\n", B);
printf("seq_len: %d\n", T);

set_zero_configs(&multi_gpu_config, 0, model.num_parameters);

// read reference information from the file saved from Python/PyTorch side
// 1) input x and y
int* x = (int*)mallocCheck(B * T * sizeof(int));
int* y = (int*)mallocCheck(B * T * sizeof(int));
freadCheck(x, sizeof(int), B*T, state_file);
freadCheck(y, sizeof(int), B*T, state_file);
// 2) results of forward pass (logits and loss)
float* expected_logits = (float*) mallocCheck(B * T * V * sizeof(float));
float* expected_loss = (float*) mallocCheck(1 * sizeof(float));
freadCheck(expected_logits, sizeof(float), B*T*V, state_file);
freadCheck(expected_loss, sizeof(float), 1, state_file);
// 3) results of backward pass (parameter gradients)
FloatParameterTensors expected_grads; // will be read from file. right now: all in fp32
float* expected_grads_memory = float_cpu_malloc_and_point_parameters(&expected_grads, model.param_elements);
freadCheck(expected_grads_memory, sizeof(float), model.num_parameters, state_file);
fcloseCheck(state_file);

// this memory will be used to do one single copy of all (mixed precision) grads to CPU grads
void* grads_memory_cpu = mallocCheck(model.num_parameters_bytes);
float* grads_memory_cpu_float = (float*)mallocCheck(model.num_parameters * sizeof(float));

// overall OK signal for the test
int allok = 1;

gpt2_allocate_state(&model, B, T);

// First, do target-free forward pass to validate logits
gpt2_forward(&model, x, B, T);
// at this point, target should be equal to expected_logits, let's compare
// copy logits to CPU so we can compare them
floatX* logits_cpu_raw = (floatX*)mallocCheck(B * T * Vp * sizeof(floatX));
float* logits_cpu = (float*)mallocCheck(B * T * Vp * sizeof(float));
memcpy(logits_cpu_raw, model.acts.output, B * T * Vp * sizeof(floatX));
for (int i = 0; i < B * T * (int)Vp; i++) {
    logits_cpu[i] = (float)logits_cpu_raw[i];
}

float logit_accuracy_threshold = 1e-3f;
float loss_diff_threshold = 1e-5f;
// FP16 and lower require very high tolerances unfortunately. TODO look into more
#if defined(ENABLE_BF16) || defined(ENABLE_F16)
logit_accuracy_threshold = 25.0f; // 15.0f was too low even without cuDNN?! :(
loss_diff_threshold = 0.05f;
#endif

// compare the output logits from the forward pass
// also careful that we don't access and compare the padded columns of logits
int logits_ok = 1;
float max_diff = 0.0f;
for (int bt = 0; bt < B*T; bt++) {
    for (int v = 0; v < (int)V; v++) {
        int i = bt * Vp + v; // linearized index
        if (i < 10) {
            printf("%f, %f\n", expected_logits[i], logits_cpu[i]);
        }
        float diff = fabsf(expected_logits[bt*V + v] - logits_cpu[i]);
        max_diff = fmaxf(max_diff, diff);
        if (diff >= logit_accuracy_threshold) {
            printf("MISMATCH AT INDEX %d,%d: ", bt, v);
            printf("%f %f\n", expected_logits[bt*V + v], logits_cpu[i]);
            logits_ok = 0;
            bt = B*T; // to break out of both loops
            break;
        }
    }
}
allok = allok && logits_ok;
if(!logits_ok) { printf("NOT "); }
printf("OK (LOGITS)\n");
printf("logit max diff: %f\n", max_diff);

// let's do 10 training iterations, following the pytorch code
float losses[10];
for (int step = 0; step < 10; step++) {
    struct timespec start, end;

/*
Matrix Multiplication, with help from oneMath BLAS (port of matmul.cuh).
Row-major logical layout everywhere (llm.c tensors are row-major):
  out(BT x OC) = inp(BT x C) * W^T + bias,  W is (OC x C) row-major.
Realised as oneMath column_major gemm with bf16 A/B and fp32 C output
(written to an fp32 buffer, then converted to bf16 with optional bias add):
  O_colm(OC x BT) = gemm(A=Wbuf trans, B=Inbuf nontrans),
  A is (C x OC) col-major == W row-major (OC x C), lda=C;
  B is (C x BT) col-major == In row-major (BT x C), ldb=C;
  C is (OC x BT) col-major == Out row-major (BT x OC), ldc=OC.
*/
#ifndef SYCL_MATMUL_H
#define SYCL_MATMUL_H

#include <assert.h>
#include <type_traits>      // std::bool_constant
#include <oneapi/math/blas.hpp>
// llmc internal imports
#include "sycl_common.h"
#include "sycl_utils.hpp"
// GELU can be either fused or non-fused (kept non-fused here; fusion flags accepted for API compat)
#include "gelu.hpp"

// ----------------------------------------------------------------------------
// SYCL kernels

// dbias[OC] += sum over BT rows of dout (deterministic: ordered accumulation per OC)
template<typename OutFloat>
inline void matmul_backward_bias(floatX* dbias_out, OutFloat* dbias, const floatX* dout, int B, int T, int OC,
                                             bool use_aux, float* aux, int aux_rows, sycl::queue& q) {
    size_t N = (size_t)B * T;
    if (use_aux) {
        // each aux row r holds partial sums over a strided subset (mirrors grid_size_y path)
        q.parallel_for(sycl::range<2>((size_t)aux_rows, (size_t)OC), [=](sycl::id<2> id) {
            size_t r = id[0]; size_t oc = id[1];
            float acc = 0.0f;
            for (size_t i = r; i < N; i += (size_t)aux_rows) {
                acc += (float)dout[i * (size_t)OC + oc];
            }
            aux[r * (size_t)OC + oc] = acc;
        }).wait();
        // deterministic reduction over aux rows in order
        q.wait();
        for (size_t oc = 0; oc < (size_t)OC; oc++) {
            float acc = (float)dbias[oc];
            for (int r = 0; r < aux_rows; r++) { acc += aux[(size_t)r * OC + oc]; }
            dbias_out[oc] = (floatX)acc;
        }
    } else {
        q.parallel_for(sycl::range<1>((size_t)OC), [=](sycl::id<1> id) {
            size_t oc = id[0];
            float acc = 0.0f;
            for (size_t i = 0; i < N; i++) {
                acc += (float)dout[i * (size_t)OC + oc];
            }
            dbias_out[oc] = (floatX)(acc + (float)dbias[oc]);
        }).wait();
    }
}

// dst[n] += sum over m rows of src (fp32), result rounded once to bf16 (deterministic order)
inline void reduce_add_sum(floatX* dst, const float* src, size_t n, size_t m, sycl::queue& q) {
    q.wait();
    for (size_t i = 0; i < n; i++) {
        float acc = 0.0f;
        for (size_t l = 0; l < m; l++) { acc += src[i + n * l]; }
        dst[i] = (floatX)((float)dst[i] + acc);
    }
}

// out(BT x OC) = inp(BT x C) @ W^T(OC x C) [+ bias], via oneMath bf16->fp32 gemm + convert kernel
inline void matmul_onemath(floatX* out, const floatX* weight, const floatX* inp, const floatX* bias,
                     int OC, int BT, int C, sycl::queue& q, float* tmp_fp32,
                     bool accumulate = false, floatX* pre_gelu = nullptr, bool backward_gelu = false,
                     floatX* gelu_src = nullptr) {
    NVTX_RANGE_FN();
    using namespace oneapi::math;
    // oneMath gemm writes fp32 C (no bf16 C support): use provided fp32 scratch
    oneapi::math::blas::column_major::gemm(q, transpose::trans, transpose::nontrans,
        (int64_t)OC, (int64_t)BT, (int64_t)C,
        1.0f, weight, (int64_t)C, inp, (int64_t)C,
        accumulate ? 1.0f : 0.0f, tmp_fp32, (int64_t)OC).wait();
    size_t N = (size_t)OC * BT;
    bool has_bias = (bias != nullptr);
    bool has_gelu_fwd = (pre_gelu != nullptr && !backward_gelu);
    // epilogue kernel: convert fp32 -> bf16 (+bias, +gelu), or dgelu-gated backward epilogue
    q.parallel_for(sycl::range<1>(N), [=](sycl::id<1> id) {
        size_t i = id[0];
        size_t oc = i % (size_t)OC;
        float v = tmp_fp32[i];
        if (backward_gelu && gelu_src != nullptr) {
            // DGELU epilogue used in QKV-backward path when fusion enabled (kept for API compat;
            // our default gelu_fusion=0 never takes this path)
            float x = (float)gelu_src[(i / (size_t)OC) * (size_t)C + oc % (size_t)C];
            float cube = 0.044715f * x * x * x;
            float tanh_arg = GELU_SCALING_FACTOR * (x + cube);
            float tanh_out = sycl::tanh(tanh_arg);
            float coshf_out = sycl::cosh(tanh_arg);
            float sech_out = 1.0f / (coshf_out * coshf_out);
            float local_grad = 0.5f * (1.0f + tanh_out) + x * 0.5f * sech_out * GELU_SCALING_FACTOR * (1.0f + 3.0f * 0.044715f * x * x);
            v = v * local_grad;
        } else {
            if (has_bias) { v += (float)bias[oc]; }
            if (has_gelu_fwd) { gelu_src[i] = (floatX)v; /* pre-activation aux */ }
        }
        float o = v;
        if (has_gelu_fwd) {
            float xi = v;
            float cube = 0.044715f * xi * xi * xi;
            o = 0.5f * xi * (1.0f + sycl::tanh(GELU_SCALING_FACTOR * (xi + cube)));
        }
        if (accumulate) {
            o += (float)out[i];
        }
        out[i] = (floatX)o;
    }).wait();
}

// Batched variant for attention: outTPL described per-batch below (row-major batches).
// Computes, for each batch b: Out(m x n) = op(A)(m x k) * op(B)(k x n) with fp32 accumulate,
// where the A/B/Out pointers are batch-strided views of row-major tensors.
inline void matmul_batched_onemath(floatX* out, const floatX* A, const floatX* B,
                     int m, int n, int k, bool transA, bool transB,
                     size_t strideOut, size_t strideA, size_t strideB, int batch_count,
                     bool accumulate, float* tmp_fp32, sycl::queue& q) {
    using namespace oneapi::math;
    // Implement via per-batch oneMath gemm calls on column-major views.
    // Row-major (m x k) == col-major (k x m). We compute Out_row(m x n) via
    // Out_col(n x m) = B_col_op * A_col_op with appropriate transpose flags:
    //   Out_row = A_row * B_row            => Out_col = B_col^T? Let's derive per case below.
    // Cases used by attention (all row-major logical):
    //  F1: preatt(T x T) = Q(T x HS) * K^T  i.e. A=Q(m=T,k=HS) N, B=K(n=T,k=HS) T
    //  F2: vaccum(T x HS) = Att(T x T) * V(T x HS): A=Att(m=T,k=T) N, B=V(n=HS,k=T) N with roles swapped
    //  B1: datt(T x T) = dOut(T x HS) * V^T : A=dOut(m=T,k=HS) N, B=V(n=T,k=HS) T
    //  B2: dv(HS x T)?? dv(T x HS) = Att^T * dOut: A=Att(m=T,k=T) T, B=dOut(n=HS,k=T) N
    //  B3: dq(T x HS) = dpreatt(T x T) * K: A=dpreatt(m=T,k=T) N, B=K(n=HS,k=T) N swapped
    //  B4: dk(T x HS) = dpreatt^T * Q: A=dpreatt(m=T,k=T) T, B=Q(n=HS,k=T) N swapped
    // The generic identity: Out_row(m x n) = Aop(m x k) * Bop(k x n)
    //   <=> Out_col(n x m) = Bop_col^T... simplest: Out_col(n x m) = gemm(Bop_as_col, Aop_as_col)
    //   with Bop_as_col = (n x k) col-major? Bop row (k x n) == col (n x k), Aop row (m x k) == col (k x m).
    //   Out_col = Bop_col * Aop_col with op flags: Bop_col is (n x k): use transB? and Aop_col is (k x m): use transA?
    //   gemm_col(C(n x m) = op1(Bb (n x k)) * op2(Ab (k x m))): op1 = nontrans if Bop row is (k x n)... Bop row-major (k x n) memory == col-major (n x k): op1=nontrans gives (n x k). op2: Aop row (m x k) == col (k x m): nontrans gives (k x m). So: C = gemm(nontrans, nontrans, n, m, k, Bbuf, n, Abuf, k).
    // With transpose variants on the row-major side, adjust flags accordingly:
    //   if transA(row): Aop = A^T where A row (k x m) i.e. requested A buffer is (m x k)?? We handle by swapping lda/flags:
    // Easiest correct approach: implement each batch with explicit transpose flags on the col-major views:
    //   Acol: buffer A interpreted col-major with dims (transA ? (m x k) : (k x m))... Instead of deriving further,
    //   implement via two tiny transpose-free paths used in practice (see attention.hpp which calls
    //   specialised wrappers). This generic function supports transA/transB on row-major semantics:
    //   Out(m x n) = op_row(A) * op_row(B), A:(m x k) or (k x m) if transA, B:(k x n) or (n x k) if transB.
    for (int b = 0; b < batch_count; b++) {
        const floatX* Ab = A + (size_t)b * strideA;
        const floatX* Bb = B + (size_t)b * strideB;
        float* Cb = tmp_fp32 + (size_t)b * (size_t)m * n;
        // col-major: Cc(n x m) = Bop^T(n x k) * Aop^T(k x m); both buffers viewed col-major.
        transpose fB = transB ? transpose::trans : transpose::nontrans;
        transpose fA = transA ? transpose::trans : transpose::nontrans;
        int64_t ldB = transB ? (int64_t)k : (int64_t)n; // col rows of Bbuf as col-major: (n x k)[N] rows=n; (k x n)[T] rows=k
        int64_t ldA = transA ? (int64_t)m : (int64_t)k; // col rows of Abuf as col-major: (k x m)[N] rows=k; (m x k)[T] rows=m
        // NOTE: with swapped argument order, m/n swap: gemm(m=n_row? ...). Cc is (n x m): gemm(n, m, k, Bb, Ab).
        oneapi::math::blas::column_major::gemm(q, fB, fA, (int64_t)n, (int64_t)m, (int64_t)k,
            1.0f, Bb, ldB, Ab, ldA, 0.0f, Cb, (int64_t)n).wait();
        // Cb col-major (n x m) == Out row-major (m x n): copy/convert out (with accumulate)
        floatX* Ob = out + (size_t)b * strideOut;
        size_t N = (size_t)m * n;
        if (!accumulate) {
            q.parallel_for(sycl::range<1>(N), [=](sycl::id<1> id) { Ob[id[0]] = (floatX)Cb[id[0]]; }).wait();
        } else {
            q.parallel_for(sycl::range<1>(N), [=](sycl::id<1> id) { Ob[id[0]] = (floatX)((float)Ob[id[0]] + Cb[id[0]]); }).wait();
        }
    }
}

