int main(int argc, char *argv[]) {
    // read in the (optional) command line arguments
    const char* train_data_pattern = "dev/data/tinyshakespeare/tiny_shakespeare_train.bin";
    const char* val_data_pattern = "dev/data/tinyshakespeare/tiny_shakespeare_val.bin";
    const char* load_filename = "gpt2_124M_bf16.bin"; // bf16 weights of the model
    const char* lr_scheduler_type = "cosine";
    const char* output_log_dir = NULL;
    int checkpoint_every = 0;
    int checkpoints_keep = 0;
    int major_checkpoint_every = 0;
    int resume = 0;
    int B = 4; // batch size
    int T = 1024; // sequence length max
    int total_batch_size = -1;
    float learning_rate = 3e-4f;
    int log_gpu_every = -1;
    int warmup_iterations = 0;
    float final_learning_rate_frac = 1.0f;
    float weight_decay = 0.0f;
    float skip_update_lossz = 0.0f;
    float skip_update_gradz = 0.0f;
    int val_loss_every = 20;
    int val_max_steps = 20;
    int sample_every = 20;
    int genT = 64;
    int overfit_single_batch = 0;
    int max_steps = -1;
    int override_enable_tf32 = 1;
    int use_master_weights = 1;
    int gelu_fusion = -1;
    int recompute = 1;
    int zero_stage = 0;
    int hellaswag_eval = 0;
    int num_processes = 1;
    int process_rank = 0;
    int gpus_per_node = 8;
    char nccl_init_method[256] = "mpi";
    char server_ip[256] = "";
    char fs_path[256] = "";
    for (int i = 1; i < argc; i+=2) {
        if (i + 1 >= argc) { error_usage(); }
        if (argv[i][0] != '-') { error_usage(); }
        if (!(strlen(argv[i]) == 2 || strlen(argv[i]) == 3)) { error_usage(); }
        if (argv[i][1] == 'i') { train_data_pattern = argv[i+1]; }
        else if (argv[i][1] == 'j') { val_data_pattern = argv[i+1]; }
        else if (argv[i][1] == 'e') { load_filename = argv[i+1]; }
        else if (argv[i][1] == 'o') { output_log_dir = argv[i+1]; }
        else if (argv[i][1] == 'n' && argv[i][2] == '\0') { checkpoint_every = atoi(argv[i+1]); }
        else if (argv[i][1] == 'y') { resume = atoi(argv[i+1]); }
        else if (argv[i][1] == 'b') { B = atoi(argv[i+1]); }
        else if (argv[i][1] == 't') { T = atoi(argv[i+1]); }
        else if (argv[i][1] == 'd') { total_batch_size = atoi(argv[i+1]); }
        else if (argv[i][1] == 'l' && argv[i][2] == '\0') { learning_rate = atof(argv[i+1]); }
        else if (argv[i][1] == 'l' && argv[i][2] == 'g') { log_gpu_every = atoi(argv[i+1]); }
        else if (argv[i][1] == 'u') { warmup_iterations = atoi(argv[i+1]); }
        else if (argv[i][1] == 'q') { final_learning_rate_frac = atof(argv[i+1]); }
        else if (argv[i][1] == 'c') { weight_decay = atof(argv[i+1]); }
        else if (argv[i][1] == 'x') { max_steps = atoi(argv[i+1]); }
        else if (argv[i][1] == 'v') { val_loss_every = atoi(argv[i+1]); }
        else if (argv[i][1] == 'm') { val_max_steps = atoi(argv[i+1]); }
        else if (argv[i][1] == 's' && argv[i][2] == '\0') { sample_every = atoi(argv[i+1]); }
        else if (argv[i][1] == 'g' && argv[i][2] == 'e') { gelu_fusion = atoi(argv[i+1]); }
        else if (argv[i][1] == 'g') { genT = atoi(argv[i+1]); }
        else if (argv[i][1] == 'a') { overfit_single_batch = atoi(argv[i+1]); }
        else if (argv[i][1] == 'f') { override_enable_tf32 = atoi(argv[i+1]); }
        else if (argv[i][1] == 'w') { use_master_weights = atoi(argv[i+1]); }
        else if (argv[i][1] == 'z') { zero_stage = atoi(argv[i+1]); }
        else if (argv[i][1] == 'r') { recompute = atoi(argv[i+1]); }
        else if (argv[i][1] == 'h') { hellaswag_eval = atoi(argv[i+1]); }
        else if (argv[i][1] == 'k') { lr_scheduler_type = argv[i+1]; }
        else if (argv[i][1] == 'p' && argv[i][2] == 'i') { strcpy(nccl_init_method, argv[i+1]); }
        else if (argv[i][1] == 'p' && argv[i][2] == 'f') { strcpy(fs_path, argv[i+1]); }
        else if (argv[i][1] == 'p' && argv[i][2] == 's') { strcpy(server_ip, argv[i+1]); }
        else if (argv[i][1] == 'p' && argv[i][2] == 'n') { num_processes = atoi(argv[i+1]); }
        else if (argv[i][1] == 'p' && argv[i][2] == 'r') { process_rank = atoi(argv[i+1]); }
        else if (argv[i][1] == 'p' && argv[i][2] == 'g') { gpus_per_node = atoi(argv[i+1]); }
        else if (argv[i][1] == 's' && argv[i][2] == 'l') { skip_update_lossz = atof(argv[i+1]); }
        else if (argv[i][1] == 's' && argv[i][2] == 'g') { skip_update_gradz = atof(argv[i+1]); }
        else if (argv[i][1] == 'n' && argv[i][2] == 'k') { checkpoints_keep = atoi(argv[i+1]); }
        else if (argv[i][1] == 'n' && argv[i][2] == 'm') { major_checkpoint_every = atoi(argv[i+1]); }

        clock_gettime(CLOCK_MONOTONIC, &start);
        gpt2_forward(&model, x, B, T);
        gpt2_backward_and_reduce(&model, x, y, 1, 0);
        clock_gettime(CLOCK_MONOTONIC, &end);
        double time_elapsed_s = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;

        if (step == 0) {
            // error checking at step 0 for reference activations

            // move the (mixed precision) grads to CPU
            memcpy(grads_memory_cpu, model.grads_memory, model.num_parameters_bytes);

            // convert all gradients to float on the CPU
            char* src_iterator = (char*)grads_memory_cpu; // can be lower precision, so we use char*
            float* dst_iterator = (float*)grads_memory_cpu_float; // float*
            float* exp_iterator = expected_grads_memory; // float* of expected gradients from Python
            float* tensors1[NUM_PARAMETER_TENSORS];
            float* tensors2[NUM_PARAMETER_TENSORS];
            for (int i = 0; i < NUM_PARAMETER_TENSORS; i++) {
                if (model.param_sizeof[i] == sizeof(float)) {
                    // float tensor => copy over directly
                    memcpy(dst_iterator, src_iterator, model.param_elements[i] * sizeof(float));
                } else {
                    // low-precision tensor => convert to float
                    assert(model.param_sizeof[i] == sizeof(floatX)); // floatX is the single non-float supported atm
                    for (size_t j = 0; j < model.param_elements[i]; j++) {
                        dst_iterator[j] = ((floatX*)src_iterator)[j]; // convert to float
                    }
                }
                // for convenience record the position of comparison for reality vs. expectation
                tensors1[i] = dst_iterator; // reality
                tensors2[i] = exp_iterator; // expectation
                // advance the iterators
                src_iterator += model.param_elements[i] * model.param_sizeof[i];
                dst_iterator += model.param_elements[i];
                exp_iterator += model.param_elements[i];
            }

            // compare the gradients on the parameters all at once, in fp32
            // I set the tolerances manually by inspecting the gradient differences for
            // a few elements of each tensor. bf16 looks ok but not amazing here.
            // It's possible we have bugs lurking, or maybe it is bf16. Not 100% sure.
            // Also, if code changes and some of these get tripped, it could be ok if it's not by too much,
            // because our use of stochastic rounding is adding some non-determinism "pepper noise".
            // In that case it's ok to extend the tolerance by a bit, after a manual review.
            // Also, different GPUs may use different matrix multiplication algorithms, so the
            // actual errors can be hardware specific.

            float grad_thresholds[NUM_PARAMETER_TENSORS] = {
                    5e-1f, 4e-3f, 1e-1f, 4e-2f,
                    5e-2f, 3.5e-2f, 2e-2f, 3e-2f,
                    5e-2f, 3e-2f, 3e-2f, 3e-2f,
                    2e-2f, 1e-2f,1e-1f,2e-2f};

            #if defined(ENABLE_FP32)
            for (int i = 0; i < NUM_PARAMETER_TENSORS; i++) {
                grad_thresholds[i] = 1e-6f;  // we can be much more precise in FP32
            }
            #endif
            const char* names[NUM_PARAMETER_TENSORS] = {
                    "wte", "wpe", "ln1w", "ln1b", "qkvw", "qkvb", "attrpojw",
                    "attprojb", "ln2w", "ln2b", "fcw", "fcb", "fcprojw", "fcprojb",
                    "lnfw", "lnfb"
            };
            size_t* count = model.param_elements;
            for(int i = 0; i < NUM_PARAMETER_TENSORS; ++i) {
                allok = allok & check_tensor(tensors1[i], tensors2[i], count[i], names[i], grad_thresholds[i]);
            }
        }

        float grad_norm = gpt2_calculate_grad_norm(&model, &multi_gpu_config);
        float grad_scale = (grad_norm > 1.0f) ? 1.0f / grad_norm : 1.0f;
        gpt2_update(&model, 1e-4f, 0.9f, 0.95f, 1e-8f, 0.0f, grad_scale, step+1, &multi_gpu_config);

        // print the timing information at the end
        printf("step %d: loss %f (took %f ms)\n", step+1, model.mean_loss, time_elapsed_s * 1000);
        // the expected losses from PyTorch were copied over after the print formatting rounded
        // them to 6 decimal places, so we do the same here
        float rounded_loss = roundf(model.mean_loss * 1000000) / 1000000;
        losses[step] = rounded_loss;
    }

    // expected losses are as follows, from Python
    float expected_losses[10] = {
        5.270009f,
        4.060681f,
        3.320085f,
        2.717550f,
        2.181066f,
        1.653923f,
        1.168050f,
        0.736873f,
        0.401021f,
        0.187493f
    };

    // compare
    for (int i = 0; i < 10; i++) {
        if (fabsf(losses[i] - expected_losses[i]) >= loss_diff_threshold) {
            printf("LOSS MISMATCH AT STEP %d: %f %f\n", i+1, losses[i], expected_losses[i]);
            allok = 0;
        } else {
            printf("loss ok at step %d: %f %f\n", i+1, losses[i], expected_losses[i]);
        }
    }

    // Finally, let's check determinism
    gpt2_write_to_checkpoint(&model, "test_gpt2cu_model.ckpt");

    DataLoader loader;
    dataloader_init(&loader, "dev/data/tinyshakespeare/tiny_shakespeare_val.bin", B, T, multi_gpu_config.process_rank, multi_gpu_config.num_processes, 1);
    save_state("test_gpt2cu_state.ckpt", 10, &model, &loader);
    int tokens[10];
    for (int step = 0; step < 10; step++) {
        dataloader_next_batch(&loader);
        gpt2_forward(&model, loader.inputs, B, T);
        gpt2_backward_and_reduce(&model, loader.inputs, loader.targets, 1, 0);
        gpt2_update(&model, 1e-4f, 0.9f, 0.95f, 1e-8f, 0.0f, 1.0f, step+11, &multi_gpu_config);
        losses[step] = model.mean_loss;
        tokens[step] = loader.inputs[0];
    }

    // reload
    gpt2_free(&model);
    gpt2_build_from_checkpoint(&model, "test_gpt2cu_model.ckpt");
    int ld_step;
    gpt2_allocate_state(&model, B, T);
    load_state(&ld_step, &model, &loader, "test_gpt2cu_state.ckpt");
    for (int step = 0; step < 10; step++) {
        dataloader_next_batch(&loader);
        gpt2_forward(&model, loader.inputs, B, T);
        gpt2_backward_and_reduce(&model, loader.inputs, loader.targets, 1, 0);
        gpt2_update(&model, 1e-4f, 0.9f, 0.95f, 1e-8f, 0.0f, 1.0f, step+11, &multi_gpu_config);

        if(loader.inputs[0] != tokens[step]) {
            printf("Nondeterminism! Token mismatch at step %d: %d vs %d\n", step, tokens[step], loader.inputs[0]);
            allok = false;
            break;
        }

        if(losses[step] != model.mean_loss) {
            printf("Nondeterminism! Loss mismatch at step %d: %.15f vs %.15f\n", step, losses[step], model.mean_loss);
            allok = false;
            break;
        } else {
            printf("loss ok at step %d: %f %f\n", step, losses[step], model.mean_loss);
        }
    }

    // final approval
    printf("overall okay: %d\n", allok);

    // delete intermediate test files
    remove("test_gpt2cu_model.ckpt");
    remove("test_gpt2cu_state.ckpt");

    // free everything
    dataloader_free(&loader);
    gpt2_free(&model);
    common_free(model);
    free(x);
    free(y);
    free(logits_cpu_raw);
    free(logits_cpu);
    free(expected_logits);
    free(expected_loss);
    free(expected_grads_memory);
    free(grads_memory_cpu);
    free(grads_memory_cpu_float);
    return allok ? EXIT_SUCCESS : EXIT_FAILURE;
}

/*
LayerNorm SYCL kernels, and also Residual, because sometimes they are fused
Port of layernorm.cuh. Reductions use SYCL group algorithms
(sycl::reduce_over_group / joint_reduce) instead of CUB/warp shuffles.
*/
#ifndef SYCL_LAYERNORM_H
#define SYCL_LAYERNORM_H

#include <assert.h>
// llmc internal imports
#include "sycl_common.h"
#include "sycl_utils.hpp"

// ----------------------------------------------------------------------------
// SYCL kernels

// layernorm forward: one work-group per row (N = B*T rows, C columns).
// Local memory holds the row tile for the variance pass.
inline void layernorm_forward(floatX* out, float* mean, float* rstd,
                       floatX* inp, const floatX* weight, const floatX* bias,
                       int B, int T, int C, sycl::queue& q) {
    NVTX_RANGE_FN();
    size_t N = (size_t)B * T;
    if (N == 0) return;
    // work-group of 256 items; each group handles one row
    size_t wg = 256;
    q.parallel_for(sycl::nd_range<1>(N * wg, wg), [=](sycl::nd_item<1> it) {
        size_t row = it.get_group(0);
        size_t lid = it.get_local_id(0);
        sycl::group<1> g = it.get_group();
        const floatX* x = inp + row * (size_t)C;
        // mean
        float sum = 0.0f;
        for (size_t c = lid; c < (size_t)C; c += wg) { sum += (float)x[c]; }
        float total = sycl::reduce_over_group(g, sum, sycl::plus<float>());
        float m = total / (float)C;
        // variance
        float vsum = 0.0f;
        for (size_t c = lid; c < (size_t)C; c += wg) {
            float d = (float)x[c] - m;
            vsum += d * d;
        }
        float vtotal = sycl::reduce_over_group(g, vsum, sycl::plus<float>());
        float s = sycl::rsqrt(vtotal / (float)C + 1e-5f);
        if (lid == 0) {
            if (mean != nullptr) { mean[row] = m; }
            if (rstd != nullptr) { rstd[row] = s; }
        }
        floatX* o = out + row * (size_t)C;
        for (size_t c = lid; c < (size_t)C; c += wg) {
            float nrm = s * ((float)x[c] - m);
            o[c] = (floatX)(nrm * (float)weight[c] + (float)bias[c]);
        }
    }).wait();
}

inline void residual_forward(floatX* out, const floatX* inp1, const floatX* inp2, size_t N, sycl::queue& q) {
    NVTX_RANGE_FN();
    size_t vec = x128::size;
    size_t nvec = CEIL_DIV(N, vec);
    q.parallel_for(sycl::range<1>(nvec), [=](sycl::id<1> id) {
        size_t idx = id[0] * vec;
        if (idx >= N) return;
        size_t rem = N - idx;
        if (rem >= vec) {
            x128 packed_out;
            x128 packed_inp1 = load128cs(inp1 + idx);
            x128 packed_inp2 = load128cs(inp2 + idx);
            for (size_t k = 0; k < vec; k++) {
                packed_out[k] = (floatX)((float)packed_inp1[k] + (float)packed_inp2[k]);
            }
            store128(out + idx, packed_out);
        } else {
            for (size_t k = 0; k < rem; k++) {
                out[idx + k] = (floatX)((float)inp1[idx + k] + (float)inp2[idx + k]);
            }
        }
    }).wait();
}

inline void fused_residual_forward5(floatX* residual, floatX* normed, float* mean, float* rstd,
                             const floatX* inp1, const floatX* inp2,
                             const floatX* weight, const floatX* bias,
                             int N, int C, sycl::queue& q) {
    // residual = inp1 + inp2, then layernorm(residual) -> normed.
    // Two-pass version (same numerics as the CUDA fallback path).
    residual_forward(residual, inp1, inp2, (size_t)N * C, q);
    layernorm_forward(normed, mean, rstd, residual, weight, bias, N, 1, C, q);
}

// layernorm backward: deterministic.
// CUDA kernel uses cross-block atomics + last-block reduction; here we compute
// per-row terms (dnorm_mean, dnorm_norm_mean) with ordered accumulation and
// accumulate dweight/dbias over rows in row order (bit-deterministic),
// while dinp uses += (read-modify-write of the residual-stream gradient).
inline void layernorm_backward(floatX* dinp, floatX* dweight, floatX* dbias, float* scratch,
                        const floatX* dout, const floatX* inp, const floatX* weight, const float* mean, const float* rstd,
                        int B, int T, int C, sycl::queue& q) {
    NVTX_RANGE_FN();
    (void)scratch;
    size_t N = (size_t)B * T;
    if (N == 0) return;
    // Pass 1: per-row dnorm_mean / dnorm_norm_mean, then dinp row update (ordered within row).
    // Also accumulate per-row dbias/dweight contributions into a host-side fp32 buffer
    // to keep the cross-row accumulation order deterministic.
    float* row_sums = sycl::malloc_shared<float>(N * 2, q); // (dnorm_mean, dnorm_norm_mean) per row
    {
        size_t wg = 256;
        q.parallel_for(sycl::nd_range<1>(N * wg, wg), [=](sycl::nd_item<1> it) {
            size_t row = it.get_group(0);
            size_t lid = it.get_local_id(0);
            sycl::group<1> g = it.get_group();
            const floatX* dout_bt = dout + row * (size_t)C;
            const floatX* inp_bt = inp + row * (size_t)C;
            float dm = 0.0f, dnm = 0.0f;
            for (size_t c = lid; c < (size_t)C; c += wg) {
                float dnorm_i = (float)weight[c] * (float)dout_bt[c];
                dm += dnorm_i;
                dnm += dnorm_i * (float)inp_bt[c];
            }
            dm = sycl::reduce_over_group(g, dm, sycl::plus<float>());
            dnm = sycl::reduce_over_group(g, dnm, sycl::plus<float>());
            if (lid == 0) {
                float mbt = mean[row];
                float rbt = rstd[row];
                row_sums[row*2+0] = dm / (float)C;
                row_sums[row*2+1] = dnm / (float)C * rbt - (dm / (float)C) * mbt * rbt;
            }
        }).wait();
    }
    // Pass 2: dinp update (one group per row; += semantics preserved)
    {
        size_t wg = 256;
        q.parallel_for(sycl::nd_range<1>(N * wg, wg), [=](sycl::nd_item<1> it) {
            size_t row = it.get_group(0);
            size_t lid = it.get_local_id(0);
            float dnorm_mean = row_sums[row*2+0];
            float dnorm_norm_mean = row_sums[row*2+1];
            float mbt = mean[row];
            float rbt = rstd[row];
            const floatX* dout_bt = dout + row * (size_t)C;
            const floatX* inp_bt = inp + row * (size_t)C;
            floatX* dinp_bt = dinp + row * (size_t)C;
            for (size_t c = lid; c < (size_t)C; c += wg) {
                float norm_bti = ((float)inp_bt[c] - mbt) * rbt;
                float dval = (float)weight[c] * (float)dout_bt[c]; // term 1
                dval -= dnorm_mean; // term 2
                dval -= norm_bti * dnorm_norm_mean; // term 3
                dval *= rbt; // final scale
                dinp_bt[c] = (floatX)((float)dinp_bt[c] + dval);
            }
        }).wait();
    }
    // Pass 3: deterministic dweight/dbias accumulation in row order on host-visible USM.
    q.wait();
    for (size_t row = 0; row < N; row++) {
        float mbt = mean[row];
        float rbt = rstd[row];
        const floatX* dout_bt = dout + row * (size_t)C;
        const floatX* inp_bt = inp + row * (size_t)C;
        for (int c = 0; c < C; c++) {
            float dout_i = (float)dout_bt[c];
            float norm_bti = ((float)inp_bt[c] - mbt) * rbt;
            dbias[c] = (floatX)((float)dbias[c] + dout_i);
            dweight[c] = (floatX)((float)dweight[c] + norm_bti * dout_i);
        }
    }
    sycl::free(row_sums, q);
}

#endif

/*
The GPT-2 Encoder, which combines two encodings: token and position
In the forward pass, both encodings are added together
In the backward pass, the gradients flow to both, handled by different kernels
SYCL 2020 port of encoder.cuh (single device, deterministic).
*/
#ifndef SYCL_ENCODER_H
#define SYCL_ENCODER_H

#include <assert.h>
#include <stdint.h>
#include <utility>              // std::pair
#include <vector>
#include <algorithm>
#include <unordered_map>
// llmc internal imports
#include "sycl_common.h"
#include "sycl_utils.hpp"

// ----------------------------------------------------------------------------
// SYCL kernels

inline void encoder_forward(floatX* out,
                     const int* inp, const floatX* wte, const floatX* wpe,
                     int B, int T, int C, sycl::queue& q) {
    NVTX_RANGE_FN();
    size_t N = (size_t)B * T * C;
    size_t vec = x128::size;
    size_t nvec = CEIL_DIV(N, vec);
    q.parallel_for(sycl::range<1>(nvec), [=](sycl::id<1> id) {
        size_t vidx = id[0];
        size_t idx = vidx * vec;
        if (idx >= N) { return; }
        size_t bt = idx / (size_t)C;
        size_t b = bt / (size_t)T;
        size_t t = bt % (size_t)T;
        size_t c = idx % (size_t)C;
        int ix = inp[b * T + t];
        floatX* out_btc = out + b * T * C + t * C + c;
        const floatX* wte_ix = wte + (size_t)ix * C + c;
        const floatX* wpe_tc = wpe + t * C + c;
        x128 packed_out;
        x128 wte128 = load128cs(wte_ix);
        x128 wpe128 = load128cs(wpe_tc);
        for (size_t k = 0; k < x128::size; k++) {
            packed_out[k] = (floatX)((float)wte128[k] + (float)wpe128[k]);
        }
        store128(out_btc, packed_out);
    }).wait();
}

// wte backward: deterministic bucketed accumulation.
// Same bucketing as CUDA version (computed on host); each bucket is accumulated
// in bucket order with a sequential, deterministic summation per channel group.
inline void encoder_backward(floatX* dwte, floatX* dwpe, floatX* scratch, // device outputs & scratch
                      int* workload_indices, int* bucket_info,    // cpu scratch buffers (4 ints per bucket)
                      const floatX* dout, const int* inp, const int* inputs_cpu, // cpu/device inputs
                      int B, int T, int C, unsigned int seed, sycl::queue& q) {
    NVTX_RANGE_FN();
    (void)inp;

    // ---- wpe backward (deterministic): each (t,c) accumulated in batch order ----
    {
        size_t vec = x128::size;
        size_t N = (size_t)T * C;
        size_t nvec = CEIL_DIV(N, vec);
        q.parallel_for(sycl::range<1>(nvec), [=](sycl::id<1> id) {
            size_t vidx = id[0];
            size_t idx = vidx * vec;
            if (idx >= N) { return; }
            size_t t = idx / (size_t)C;
            size_t c = idx % (size_t)C;
            float accum[x128::size] = {0.0f};
            for (int b = 0; b < B; b++) {
