    float_bits = (rounded_bits > threshold) ? (float_bits | 0xFFFFu) : (float_bits & ~0xFFFFu);
    float rounded;
    memcpy(&rounded, &float_bits, sizeof(rounded));
    *out = sycl::ext::oneapi::bfloat16(rounded);
}

