    size_t vec = x128::size;
    size_t vecs_per_group = c_per_group / vec; // 32
    q.memcpy(d_workload, workload_indices, total_items * sizeof(int));
    q.memcpy(d_buckets, bucket_info, (size_t)num_buckets * 4 * sizeof(int));
