float gpt2_estimate_mfu(GPT2 *model, int num_tokens, float dt) {
    size_t N = model->num_parameters;
    int L = model->config.num_layers;
    int C = model->config.channels;
    int T = model->seq_len;
    size_t flops_per_token = 6 * N + (size_t)6 * L * C * T;
    size_t flops_per_step = flops_per_token * num_tokens;
    // express our flops throughput as ratio of A100 bfloat16 peak flops
    float flops_achieved = (float)flops_per_step * (1.0f / dt); // per second
    float flops_promised = get_flops_promised(sycl_device_name.c_str(), PRECISION_MODE) * 1e12f;
    if(flops_promised < 0) {
        return -1.f;   // don't know
    }
    float mfu = flops_achieved / flops_promised;
    return mfu;
}

void gpt2_free(GPT2 *model) {
    if (model->params_memory) { sycl::free(model->params_memory, sycl_queue); model->params_memory = nullptr; }
    if (model->grads_memory) { sycl::free(model->grads_memory, sycl_queue); model->grads_memory = nullptr; }
    if (model->m_memory) { sycl::free(model->m_memory, sycl_queue); model->m_memory = nullptr; }
    if (model->v_memory) { sycl::free(model->v_memory, sycl_queue); model->v_memory = nullptr; }
    if (model->master_weights) { sycl::free(model->master_weights, sycl_queue); model->master_weights = nullptr; }
    if (model->acts_memory) { sycl::free(model->acts_memory, sycl_queue); model->acts_memory = nullptr; }
    if (model->acts.gemm_scratch) { sycl::free(model->acts.gemm_scratch, sycl_queue); model->acts.gemm_scratch = nullptr; }
    if (model->inputs) { sycl::free(model->inputs, sycl_queue); model->inputs = nullptr; }
    if (model->targets) { sycl::free(model->targets, sycl_queue); model->targets = nullptr; }
    if (model->accumulated_mean_loss) { sycl::free(model->accumulated_mean_loss, sycl_queue); model->accumulated_mean_loss = nullptr; }
    if (model->cpu_losses) { free(model->cpu_losses); model->cpu_losses = nullptr; }
    free(model->workload_indices); model->workload_indices = nullptr;
    free(model->bucket_info); model->bucket_info = nullptr;
}

