using bf16 = sycl::ext::oneapi::bfloat16;
int main() {
  sycl::queue q(sycl::default_selector_v, sycl::property::queue::in_order{});
  const int M=4, N=8, K=6;
  bf16* A = sycl::malloc_device<bf16>(M*K, q);
  bf16* B = sycl::malloc_device<bf16>(K*N, q);
  float* C = sycl::malloc_device<float>(M*N, q);
  // init A,B on device
  q.parallel_for(sycl::range<1>(M*K), [=](sycl::id<1> id){ A[id[0]] = (bf16)0.5f; }).wait();
  q.parallel_for(sycl::range<1>(K*N), [=](sycl::id<1> id){ B[id[0]] = (bf16)0.25f; }).wait();
  // row-major MxK * KxN via col-major gemm: C_col(N x M) = gemm(B? ...) use same pattern as matmul_onemath
  // Out_row(M x N) = A(MxK)*B(KxN): Out_col(N x M) = B_col(NxK, nontrans) * A_col(KxM, nontrans)?? 
  // simpler: C = A*B with trans flags like code: gemm(trans, nontrans, N, M, K, B, K, A, K, C, N)
  oneapi::math::blas::column_major::gemm(q, oneapi::math::transpose::trans, oneapi::math::transpose::nontrans,
    (int64_t)N, (int64_t)M, (int64_t)K, 1.0f, B, (int64_t)K, A, (int64_t)K, 0.0f, C, (int64_t)N).wait();
  float h[32]; q.memcpy(h, C, sizeof(h)).wait();
  printf("C[0]=%f expect %f\n", h[0], (float)(K*0.5*0.25));
  sycl::free(A,q); sycl::free(B,q); sycl::free(C,q);
  return 0;
}
