  size_t Vp=hdr[7], C=hdr[6], maxT=hdr[2], L=hdr[4];
  size_t n = Vp*C + maxT*C + L*C + L*C + L*3*C*C + L*3*C + L*C*C + L*C + L*C + L*C + L*4*C*C + L*4*C + L*C*4*C + L*C + C + C;
