inline void file_to_device(void* dest, FILE* src, size_t num_bytes, size_t buffer_size, sycl::queue& q) {
    if (num_bytes == 0) { return; }
    size_t chunk = buffer_size != 0 ? buffer_size : (size_t)(32 * 1024 * 1024);
    char* staging = (char*)mallocCheck(chunk < num_bytes ? chunk : num_bytes);
    size_t off = 0;
    while (off < num_bytes) {
        size_t n = std::min(chunk, num_bytes - off);
        freadCheck(staging, 1, n, src);
        q.memcpy((char*)dest + off, staging, n);
        off += n;
    }
    // the staging buffer is reused for every chunk: wait for all copies before freeing it
    q.wait();
    free(staging);
    // file contents are consumed by later device work; the in-order queue
    // already orders them after the copies, no extra wait needed here.
}

