#include <sycl/sycl.hpp>
#include <cstdio>
int main() {
  sycl::queue q(sycl::default_selector_v, sycl::property::queue::in_order{});
  const int N = 1024*1024;
  float* d = sycl::malloc_device<float>(N, q);
  // host direct write (what MKL does inside oneMath)
  for (int i=0;i<N;i++) d[i] = (float)i * 0.5f;
  // device kernel reads WITHOUT any intervening runtime op
  float* o = sycl::malloc_device<float>(N, q);
  q.parallel_for(sycl::range<1>(N), [=](sycl::id<1> id){ o[id[0]] = d[id[0]] * 2.0f; });
  float* h = (float*)malloc(N*sizeof(float));
  q.memcpy(h, o, N*sizeof(float)).wait();
  int bad=0; for(int i=0;i<N;i++){ if(h[i] != (float)i) { if(bad<5)printf("mismatch at %d: %f vs %f\n",i,h[i],(float)i); bad++; } }
  printf("bad=%d\n", bad);
  // variant 2: host write, then q.memset unrelated? then kernel
  for (int i=0;i<N;i++) d[i] = (float)i * 1.0f;
  q.parallel_for(sycl::range<1>(N), [=](sycl::id<1> id){ o[id[0]] = d[id[0]]; });
  q.memcpy(h, o, N*sizeof(float)).wait();
  bad=0; for(int i=0;i<N;i++){ if(h[i] != (float)i) bad++; }
  printf("variant2 bad=%d\n", bad);
  return 0;
}
