#include <sycl/sycl.hpp>
#include <sycl/ext/oneapi/bfloat16.hpp>
#include <cstdio>
#include <cmath>
using bf16 = sycl::ext::oneapi::bfloat16;
typedef bf16 floatX;
void batched(floatX* out, const floatX* A, const floatX* B,
             int m, int n, int k, bool transA, bool transB,
             size_t strideOut, size_t strideA, size_t strideB, int batch_count,
             bool accumulate, sycl::queue& q) {
    size_t total = (size_t)batch_count * (size_t)m * (size_t)n;
    q.parallel_for(sycl::range<1>(total), [=](sycl::id<1> id) {
        size_t gid = id[0];
        size_t col = gid % (size_t)n;
        size_t tmp = gid / (size_t)n;
        size_t row = tmp % (size_t)m;
        size_t b = tmp / (size_t)m;
        const floatX* Ab = A + b * strideA;
        const floatX* Bb = B + b * strideB;
        floatX* Ob = out + b * strideOut;
        float acc = 0.0f;
        if (!transA && !transB) {
            const floatX* arow = Ab + row * (size_t)k;
            for (int l = 0; l < k; l++) acc += (float)arow[l] * (float)Bb[(size_t)l * n + col];
        } else if (!transA && transB) {
            const floatX* arow = Ab + row * (size_t)k;
            for (int l = 0; l < k; l++) acc += (float)arow[l] * (float)Bb[col * (size_t)k + l];
        } else if (transA && !transB) {
            for (int l = 0; l < k; l++) acc += (float)Ab[(size_t)l * m + row] * (float)Bb[(size_t)l * n + col];
        } else {
            for (int l = 0; l < k; l++) acc += (float)Ab[(size_t)l * m + row] * (float)Bb[col * (size_t)k + l];
        }
        Ob[row * (size_t)n + col] = (floatX)acc;
    }).wait();
}
int main() {
  sycl::queue q(sycl::default_selector_v, sycl::property::queue::in_order{});
  // F1 case with O(1) values, host reference
  int T=8, HS=4, batch=3;
  size_t nQ=(size_t)batch*T*HS, nP=(size_t)batch*T*T;
  float *hQ=new float[nQ], *hK=new float[nQ];
  for(size_t i=0;i<nQ;i++){ hQ[i]=0.5f+0.01f*(i%17); hK[i]=0.25f+0.01f*(i%13); }
  bf16 *Q=sycl::malloc_device<bf16>(nQ,q), *K=sycl::malloc_device<bf16>(nQ,q), *P=sycl::malloc_device<bf16>(nP,q);
  // upload as bf16 (round like real pipeline)
  bf16 *t=new bf16[nQ];
  for(size_t i=0;i<nQ;i++) t[i]=(bf16)hQ[i];
  q.memcpy(Q,t,nQ*sizeof(bf16)).wait();
  for(size_t i=0;i<nQ;i++) t[i]=(bf16)hK[i];
  q.memcpy(K,t,nQ*sizeof(bf16)).wait();
  // host reference from ROUNDED values
  bf16 *rQ=new bf16[nQ], *rK=new bf16[nQ];
  q.memcpy(rQ,Q,nQ*sizeof(bf16)).wait(); q.memcpy(rK,K,nQ*sizeof(bf16)).wait();
  batched(P,Q,K,T,T,HS,false,true,(size_t)T*T,(size_t)T*HS,(size_t)T*HS,batch,false,q);
  bf16 *hP=new bf16[nP]; q.memcpy(hP,P,nP*sizeof(bf16)).wait();
  double maxd=0;
  for(int b=0;b<batch;b++) for(int r=0;r<T;r++) for(int c=0;c<T;c++){
    float acc=0; for(int l=0;l<HS;l++) acc += (float)rQ[b*T*HS+r*HS+l]*(float)rK[b*T*HS+c*HS+l];
    float got=(float)hP[b*T*T+r*T+c];
    double d=fabs(got-acc); if(d>maxd)maxd=d;
  }
