  bf16 *A=sycl::malloc_device<bf16>(nP,q), *V=sycl::malloc_device<bf16>(nV,q), *O=sycl::malloc_device<bf16>(nV,q);
  bf16 *ta=new bf16[nP]; for(size_t i=0;i<nP;i++) ta[i]=(bf16)hA[i];
  q.memcpy(A,ta,nP*sizeof(bf16)).wait();
  q.memcpy(V,rQ,nV*sizeof(bf16)).wait(); // reuse rQ values as V
  batched(O,A,V,T,HS,T,false,false,(size_t)T*HS,(size_t)T*T,(size_t)T*HS,batch,false,q);
  bf16 *hO=new bf16[nV]; q.memcpy(hO,O,nV*sizeof(bf16)).wait();
  bf16 *rA=new bf16[nP]; q.memcpy(rA,A,nP*sizeof(bf16)).wait();
  maxd=0;
  for(int b=0;b<batch;b++) for(int r=0;r<T;r++) for(int c=0;c<HS;c++){
    float acc=0; for(int l=0;l<T;l++) acc += (float)rA[b*T*T+r*T+l]*(float)rQ[b*T*HS+l*HS+c];
    float got=(float)hO[b*T*HS+r*HS+c];
    double d=fabs(got-acc); if(d>maxd)maxd=d;
  }
  printf("F2(N,N) maxdiff vs host ref: %f\n", maxd);
  return 0;
}
