inline void permute(floatX* qo, floatX* ko, floatX* vo,
                               const floatX* inp,
                               int B, int N, int NH, int d, sycl::queue& qq) {
    // ko is written TRANSPOSED per batch+head: ko[(b*NH+nh_)*d*N + h*N + n] holds
    // K[b,nh_,n,h]. This makes the QK^T matmul a coalesced (N,N) batched GEMM
    // (same values, same per-element summation order downstream: bitwise identical).
    sycl::queue& q = qq;
    size_t total = (size_t)B * NH * N * d;
    q.parallel_for(sycl::range<1>(total), [=](sycl::id<1> id) {
        size_t idx = id[0];
        size_t b = idx / ((size_t)NH * N * d);
        size_t rest = idx % ((size_t)NH * N * d);
        size_t nh_ = rest / ((size_t)N * d);
        rest = rest % ((size_t)N * d);
        size_t n = rest / (size_t)d;
        size_t d_ = rest % (size_t)d;
        size_t inp_idx = (b * N * 3 * NH * d) + (n * 3 * NH * d) + (nh_ * d) + d_;
        qo[idx] = inp[inp_idx];
        // transposed store: row h=d_, column n (per batch/head matrix is d x N)
        ko[((b * (size_t)NH + nh_) * (size_t)d + d_) * (size_t)N + n] = inp[inp_idx + (size_t)NH * d];
        vo[idx] = inp[inp_idx + 2 * (size_t)NH * d];
    });
}

