// Batched attention matmul in a SINGLE kernel launch over all batches:
// for each batch b: Out(m x n) = op_row(A)(m x k) * op_row(B)(k x n),
// fp32 accumulation, rounded once to bf16. Row-major logical layout, exactly
// like the previous per-batch oneMath path.
// GPU-friendly 16x16 output tiling with local-memory staging (TM=TN=16,
// TK=32): all global loads are coalesced for every transpose combination,
// while each output element still accumulates l=0..k-1 in index order, so the
// result is bitwise identical to the naive kernel (deterministic, independent
// of work-group scheduling). One work-group (256 work-items) per tile;
// groups are 1-D flattened (batch, m-tile, n-tile) for backend portability.
inline void matmul_batched_onemath(floatX* out, const floatX* A, const floatX* B,
                     int m, int n, int k, bool transA, bool transB,
                     size_t strideOut, size_t strideA, size_t strideB, int batch_count,
                     bool accumulate, float* tmp_fp32, sycl::queue& q) {
    (void)tmp_fp32; // no longer needed: direct bf16->fp32->bf16 in one kernel
    if (batch_count <= 0 || m <= 0 || n <= 0 || k <= 0) { return; }
    constexpr int TM = 16;
    constexpr int TN = 16;
    constexpr int TK = 32;
    constexpr int WG = TM * TN; // 256 work-items per tile
    size_t mt = CEIL_DIV((size_t)m, TM);
    size_t nt = CEIL_DIV((size_t)n, TN);
    size_t groups = (size_t)batch_count * mt * nt;
    // A tile (TM x TK) / B tile (TK x TN) staging, padded columns to avoid
    // local-memory bank conflicts on GPUs. Stored transposed when the operand
    // itself is transposed so that compute always reads As[t][l]*Bs[l][t].
    sycl::range<1> local_flat(2 * (size_t)TM * TK + 32);
    q.parallel_for(sycl::nd_range<1>(groups * WG, WG), [=](sycl::nd_item<1> it) {
        size_t gid = it.get_group(0);
        size_t lid = it.get_local_id(0);
        size_t lr = lid / TN; // 0..15 row in tile
        size_t lc = lid % TN; // 0..15 col in tile
        size_t tmp = gid / nt;
        size_t tn = gid % nt;
        size_t b = tmp / mt;
        size_t tm = tmp % mt;
        const floatX* Ab = A + b * strideA;
        const floatX* Bb = B + b * strideB;
        floatX* Ob = out + b * strideOut;
        sycl::group<1> g = it.get_group();
        // partition local memory: A's tile then B's tile
        sycl::private_ptr<float[]> priv;
        (void)priv;
        // use local accessors via group local memory
        float* As = sycl::ext::oneapi::group_local_memory<float[TM * (TK + 1)]>(g);
        float* Bs = sycl::ext::oneapi::group_local_memory<float[TN * (TK + 1)]>(g);
        auto Aelem = [&](int r, int c) -> float& { return As[(size_t)r * (TK + 1) + c]; };
        auto Belem = [&](int r, int c) -> float& { return Bs[(size_t)r * (TK + 1) + c]; };
        float acc = 0.0f;
        // helpers to fetch logical operand elements (row-major semantics)
        auto getA = [&](int r, int l) -> float {
            if (!transA) { return (float)Ab[(size_t)r * k + l]; }
            return (float)Ab[(size_t)l * m + r];
        };
        auto getB = [&](int l, int c) -> float {
            if (!transB) { return (float)Bb[(size_t)l * n + c]; }
            return (float)Bb[(size_t)c * k + l];
