            // (klen x TN); out-of-range lanes write 0 (masked by bounds below)
            for (int t = (int)lid; t < TM * TK; t += WG) {
                int r = t / TK;
                int c = t % TK;
                float av = 0.0f, bv = 0.0f;
                int gr = (int)(tm * TM) + r;
                int gc = (int)(tn * TN) + r; // note: B tile indexed [k][col]
                if (c < klen) {
                    if (gr < m) {
                        // A element Aop[gr, k0+c]: coalesced when consecutive
                        // lanes (c) map to consecutive addresses
                        if (!transA) { av = (float)Ab[(size_t)gr * k + (k0 + c)]; }
                        else { av = (float)Ab[(size_t)(k0 + c) * m + gr]; }
                    }
                    if (gc < n) {
                        if (!transB) { bv = (float)Bb[(size_t)(k0 + c) * n + gc]; }
                        else { bv = (float)Bb[(size_t)gc * k + (k0 + c)]; }
                    }
                }
                // store: A tile as [r][c], B tile as [c][r]-transposed-safe layout
                // [k][col] so compute reads Bs[l][lc] with l the k index
                Aelem(r, c) = av;
                // B tile element for k-offset c, output-col r
                Belem(c, r) = bv;
            }
            sycl::group_barrier(g);
            int row = (int)(tm * TM) + (int)lr;
            int col = (int)(tn * TN) + (int)lc;
            if (row < m && col < n) {
