            float av = 0.0f, bv = 0.0f;
            if (ac < klen) {
                int gr = tm * TM + ar;
                int gc = tn * TN + br;
                if (gr < m) {
                    if (!TA) { av = (float)Ab[(size_t)gr * k + (k0 + ac)]; }
                    else { av = (float)Ab[(size_t)(k0 + ac) * m + gr]; }
                }
                if (gc < n) {
                    if (!TB) { bv = (float)Bb[(size_t)(k0 + ac) * n + gc]; }
                    else { bv = (float)Bb[(size_t)gc * k + (k0 + ac)]; }
                }
                // NOTE: for the transposed operand the tile is stored
                // transposed ([c][r]) so compute indexing stays uniform;
                // the load itself stays coalesced (see analysis).
                if (!TA) { Aat(ar, ac) = av; } else { Aat(ac, ar) = av; }
                if (!TB) { Bat(ac, br) = bv; } else { Bat(br, ac) = bv; }
            } else {
                // k-tail lanes: keep tile deterministic (never read, but avoid
                // stale reuse across k0 iterations)
                if (!TA) { Aat(ar, ac) = 0.0f; } else { Aat(ac, ar) = 0.0f; }
                if (!TB) { Bat(ac, br) = 0.0f; } else { Bat(br, ac) = 0.0f; }
            }
            (void)bc; (void)br;
        }
        sycl::group_barrier(g);
        if (active) {
            for (int l = 0; l < klen; l++) {
                float a = TA ? Aat(l, (int)lr) : Aat((int)lr, l);
                float b = TB ? Bat((int)lc, l) : Bat(l, (int)lc);
                acc += a * b;
            }
        }
        sycl::group_barrier(g);
    }
    if (active) {
        size_t o = (size_t)row * n + col;
        if (accumulate) {
            Ob[o] = (floatX)((float)Ob[o] + acc);
        } else {
            Ob[o] = (floatX)acc;
        }
    }
}

// Batched attention matmul in a SINGLE kernel launch over all batches:
// for each batch b: Out(m x n) = op_row(A)(m x k) * op_row(B)(k x n),
// fp32 accumulation, rounded once to bf16. Row-major logical layout, exactly
// like the previous per-batch oneMath path; 16x16 tiling with local-memory
// staging keeps every global load coalesced on GPUs (see batched_tile).
inline void matmul_batched_onemath(floatX* out, const floatX* A, const floatX* B,
                     int m, int n, int k, bool transA, bool transB,
                     size_t strideOut, size_t strideA, size_t strideB, int batch_count,
                     bool accumulate, float* tmp_fp32, sycl::queue& q) {
    (void)tmp_fp32; // no longer needed: direct bf16->fp32->bf16 in one kernel
    if (batch_count <= 0 || m <= 0 || n <= 0 || k <= 0) { return; }
    constexpr int TM = 16;
    constexpr int TN = 16;
    constexpr int WG = TM * TN; // 256 work-items per tile
    size_t mt = CEIL_DIV((size_t)m, TM);
    size_t nt = CEIL_DIV((size_t)n, TN);
    size_t groups = (size_t)batch_count * mt * nt;
    // dispatch on the transpose combination so inner loops have no branches
    int variant = (transA ? 2 : 0) + (transB ? 1 : 0);
    for (int v = 0; v < 4; v++) {
        if (v != variant) { continue; }
        sycl::local_accessor<float, 2> As(sycl::range<2>(TM, 33), q);
        sycl::local_accessor<float, 2> Bs(sycl::range<2>(32, 17), q);
        // NOTE: local accessors must be constructed per submission; we submit
        // exactly one kernel below (the loop above selects at host level).
        if (v == 0) {
            q.parallel_for(sycl::nd_range<1>(groups * WG, WG), [=](sycl::nd_item<1> it) {
                size_t gid = it.get_group(0);
                size_t tn = gid % nt;
                size_t t2 = gid / nt;
                size_t b = t2 / mt;
                size_t tm = t2 % mt;
                batched_tile<false, false>(out + b * strideOut, A + b * strideA, B + b * strideB,
                    m, n, k, (int)tm, (int)tn, accumulate, it, As, Bs);
            });
        } else if (v == 1) {
            q.parallel_for(sycl::nd_range<1>(groups * WG, WG), [=](sycl::nd_item<1> it) {
                size_t gid = it.get_group(0);
                size_t tn = gid % nt;
                size_t t2 = gid / nt;
                size_t b = t2 / mt;
                size_t tm = t2 % mt;
                batched_tile<false, true>(out + b * strideOut, A + b * strideA, B + b * strideB,
                    m, n, k, (int)tm, (int)tn, accumulate, it, As, Bs);
            });
        } else if (v == 2) {
            q.parallel_for(sycl::nd_range<1>(groups * WG, WG), [=](sycl::nd_item<1> it) {
                size_t gid = it.get_group(0);
                size_t tn = gid % nt;
                size_t t2 = gid / nt;
                size_t b = t2 / mt;
                size_t tm = t2 % mt;
                batched_tile<true, false>(out + b * strideOut, A + b * strideA, B + b * strideB,
                    m, n, k, (int)tm, (int)tn, accumulate, it, As, Bs);
            });
        } else {
            q.parallel_for(sycl::nd_range<1>(groups * WG, WG), [=](sycl::nd_item<1> it) {
                size_t gid = it.get_group(0);
                size_t tn = gid % nt;
                size_t t2 = gid / nt;
                size_t b = t2 / mt;
                size_t tm = t2 % mt;
                batched_tile<true, true>(out + b * strideOut, A + b * strideA, B + b * strideB,
                    m, n, k, (int)tm, (int)tn, accumulate, it, As, Bs);
            });
        }
    }
}

