#include "llmc/sycl_common.h"
#include "llmc/matmul.hpp"
#include <cstdio>
#include <cmath>
sycl::queue sycl_queue;
int main() {
  sycl_queue = sycl::queue(sycl::default_selector_v, sycl::property::queue::in_order{});
  struct Case { int m,n,k,ta,tb; };
  Case cases[] = {{64,64,64,0,1},{64,64,64,0,0},{64,64,64,1,0},{64,64,64,1,1},
                  {64,64,64,0,1},{37,45,21,0,1},{37,45,21,1,0},{45,37,21,0,0},{45,37,21,1,1},
                  {8,8,4,0,1},{1024,64,64,0,1},{64,1024,64,1,0}};
  for (auto cc : cases) {
    int m=cc.m,n=cc.n,k=cc.k, batch=3;
    size_t sA = (cc.ta?(size_t)k*m:(size_t)m*k), sB = (cc.tb?(size_t)n*k:(size_t)k*n);
    float *hA=new float[sA], *hB=new float[sB];
    for(size_t i=0;i<sA;i++) hA[i]=0.05f*((i*7)%13)-0.3f;
    for(size_t i=0;i<sB;i++) hB[i]=0.05f*((i*11)%17)-0.2f;
    bf16wrap *tA=new bf16wrap[sA], *tB=new bf16wrap[sB];
    (void)tA; (void)tB;
    floatX *A=sycl::malloc_device<floatX>(batch*sA,sycl_queue), *B=sycl::malloc_device<floatX>(batch*sB,sycl_queue), *O=sycl::malloc_device<floatX>((size_t)batch*m*n,sycl_queue);
    floatX *hAx=new floatX[sA], *hBx=new floatX[sB];
    for(size_t i=0;i<sA;i++) hAx[i]=(floatX)hA[i];
    for(size_t i=0;i<sB;i++) hBx[i]=(floatX)hB[i];
    for(int b=0;b<batch;b++){ sycl_queue.memcpy(A+b*sA,hAx,sA*sizeof(floatX)).wait(); sycl_queue.memcpy(B+b*sB,hBx,sB*sizeof(floatX)).wait(); }
    // host ref from ROUNDED values
    floatX *rA=new floatX[sA], *rB=new floatX[sB];
    sycl_queue.memcpy(rA,A,sA*sizeof(floatX)).wait(); sycl_queue.memcpy(rB,B,sB*sizeof(floatX)).wait();
    matmul_batched_onemath(O,A,B,m,n,k,cc.ta,cc.tb,(size_t)m*n,sA,sB,batch,false,nullptr,sycl_queue);
    floatX *hO=new floatX[(size_t)batch*m*n];
    sycl_queue.memcpy(hO,O,(size_t)batch*m*n*sizeof(floatX)).wait();
    double maxd=0;
    for(int b=0;b<batch;b++) for(int r=0;r<m;r++) for(int c=0;c<n;c++){
      float acc=0; for(int l=0;l<k;l++){
        float a = cc.ta ? (float)rA[l*m+r] : (float)rA[r*k+l];
        float bb = cc.tb ? (float)rB[c*k+l] : (float)rB[l*n+c];
        acc += a*bb;
      }
      float got=(float)hO[(size_t)b*m*n+r*n+c];
      floatX refe=(floatX)acc;
      double d=fabs(got-(float)refe); if(d>maxd)maxd=d;
    }
    printf("m=%d n=%d k=%d TA=%d TB=%d maxdiff=%f %s\n", m,n,k,cc.ta,cc.tb, maxd, maxd<0.02?"OK":"FAIL");
    delete[] hA; delete[] hB; delete[] hAx; delete[] hBx; delete[] rA; delete[] rB; delete[] hO; delete[] tA; delete[] tB;
    sycl::free(A,sycl_queue); sycl::free(B,sycl_queue); sycl::free(O,sycl_queue);
  }
  return 0;
}
